INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (1, 'Química Sanguínea 6 Elementos', 'Ayuno estricto de 8 a 12 horas.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (2, 'Biometría Hemática Completa', 'No requiere ayuno estricto.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (3, 'Perfil Lipídico Completo', 'Ayuno de 12 horas; evitar alcohol 24h.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (4, 'Hemoglobina Glucosilada (HbA1c)', 'No requiere ayuno.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (5, 'Pruebas de Función Hepática', 'Ayuno de 8 horas.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (6, 'Electrolitos Séricos (Na, K, Cl)', 'Ayuno de 8 horas.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (7, 'Examen General de Orina (EGO)', 'Primer chorro de la primera orina de la mañana.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (8, 'Urocultivo con Antibiograma', 'Aseo previo; chorro medio.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (9, 'Depuración de Creatinina 24h', 'Recolectar toda la orina de 24 horas.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (10, 'Microalbuminuria en Orina', 'Primera orina de la mañana.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (11, 'Prueba de Embarazo en Orina', 'Primera orina matutina.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (12, 'Coproparasitoscópico Seriado (3 muestras)', 'Recolectar en días consecutivos.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (13, 'Coprocultivo', 'Muestra reciente sin contaminación de orina.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (14, 'Sangre Oculta en Heces', 'Dieta sin carnes rojas 48h previas.') ON CONFLICT DO NOTHING;
INSERT INTO estudio (id_estudio, nombre_estudio, indicaciones_previas) VALUES (15, 'Rotavirus en Heces', 'Muestra diarreica fresca.') ON CONFLICT DO NOTHING;
